argv:
$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type -AssemblyName UIAutomationTypes
$edge=Get-Process msedge -ErrorAction SilentlyContinue | Where-Object {$_.MainWindowHandle -ne 0} | Select-Object -First 1
if($null -eq $edge){throw 'Edge not visible'}
Start-Sleep -Seconds 4
$root=[System.Windows.Automation.AutomationElement]::FromHandle($edge.MainWindowHandle)
$all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition)
$hits=@()
$images=@()
$address=''
for($i=0;$i -lt $all.Count;$i++){
  $e=$all.Item($i)
  $ct=$e.Current.ControlType.ProgrammaticName
  $name=[string]$e.Current.Name
  if($ct -eq 'ControlType.Edit' -and [string]$e.Current.AutomationId -eq 'view_1017'){
    try{$vp=$e.GetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern);$address=[string]$vp.Current.Value}catch{}
  }
  if($name -like '*剛剛真的看著 ChatGPT*' -or $name -like '*你最想把哪件事丟給兩個 AI 一起完成*'){
    $r=$e.Current.BoundingRectangle
    $hits += [pscustomobject]@{type=$ct;name=$name;x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height}
  }
  if($ct -eq 'ControlType.Image'){
    $r=$e.Current.BoundingRectangle
    if(-not [double]::IsInfinity($r.Y) -and $r.Y -gt 250 -and $r.Y -lt 1400){
      if($r.Width -gt 200 -and $r.Height -gt 200){
        $images += [pscustomobject]@{name=$name;x=[string]$r.X;y=[string]$r.Y;w=[string]$r.Width;h=[string]$r.Height}
      }
    }
  }
}
[pscustomobject]@{title=$edge.MainWindowTitle;address=$address;post_hits=$hits;large_images=$images}|ConvertTo-Json -Depth 6 -Compress
